//! Local vendor samples are deliberately not distributed. Expected values were
//! transcribed from i2 Standard 1.1.4.457 in VMware, not generated by i3rs.
use i3rs_core::report::{ReportBoundary, ReportSeries, report_statistics};
use i3rs_core::{Interpolation, LdFile, LdxFile, ranges::RangeKind};
fn fixture(name: &str) -> std::path::PathBuf {
    std::path::PathBuf::from(
        std::env::var("I3RS_I2_SAMPLES").expect("set I3RS_I2_SAMPLES to local sample directory"),
    )
    .join(name)
}
fn summary(ld: &LdFile, channel: &str, start: f64, end: f64) -> i3rs_core::report::ReportSummary {
    let c = ld.find_channel_by_name(channel).unwrap_or_else(|| {
        panic!(
            "missing {channel}; channels: {:?}",
            ld.channels.iter().map(|c| &c.name).collect::<Vec<_>>()
        )
    });
    let data = ld.read_channel_data(c).unwrap();
    report_statistics(
        &ReportSeries {
            data: &data,
            freq: c.freq,
            interpolation: Interpolation::Linear,
            scale: 1.,
            offset: 0.,
        },
        &[(start, end)],
        ReportBoundary::Interpolate,
    )
}
#[test]
#[ignore = "requires local MoTeC Drag sample; set I3RS_I2_SAMPLES"]
fn drag_time_slip_and_rpm_match_i2() {
    let ld = LdFile::open(fixture("Drag.ld")).unwrap();
    let a = LdxFile::open(fixture("Drag.ldx"))
        .unwrap()
        .specialty_analysis("drag".into(), ld.duration_secs())
        .unwrap()
        .unwrap();
    let run = a.ranges.iter().find(|r| r.kind == RangeKind::Run).unwrap();
    assert_eq!(run.start, 176.750);
    assert_eq!(run.reaction_time, Some(0.4));
    assert_eq!(a.drag_setup.ratios, [1.6, 1.28, 1.]);
    let times = i3rs_core::drag::milestone_times(run, a.drag_runs.get(&run.id), None);
    assert_eq!(
        times,
        [Some(1.2), Some(2.81), Some(4.07), Some(5.16), Some(6.138)]
    );
    let mut previous = 0.;
    for (end, expected) in times.into_iter().flatten().zip([
        [5327., 8240., 7686., 5327., 8240.],
        [8240., 8904., 8612., 8240., 8815.],
        [8796., 9114., 8957., 8815., 9089.],
    ]) {
        let s = summary(&ld, "Engine RPM", run.start + previous, run.start + end);
        let actual = [
            s.min.unwrap(),
            s.max.unwrap(),
            s.average.unwrap(),
            s.start.unwrap(),
            s.end.unwrap(),
        ];
        println!("{previous:.3}..{end:.3}: {actual:?}");
        for (v, e) in actual.into_iter().zip(expected) {
            assert!((v - e).abs() < 1., "{v} != {e}");
        }
        previous = end;
    }
}
#[test]
#[ignore = "requires local MoTeC Rally sample; set I3RS_I2_SAMPLES"]
fn rally_stage_reports_match_i2() {
    let ld = LdFile::open(fixture("Rally.ld")).unwrap();
    let a = LdxFile::open(fixture("Rally.ldx"))
        .unwrap()
        .specialty_analysis("rally".into(), ld.duration_secs())
        .unwrap()
        .unwrap();
    let stages: Vec<_> = a
        .ranges
        .iter()
        .filter(|r| r.kind == RangeKind::Stage)
        .collect();
    assert_eq!(stages.len(), 2);
    for (r, expected) in stages.into_iter().zip([
        [343.9, 1176., 5730., 3561., 94.9],
        [347.1, 1068., 6102., 3690., 92.6],
    ]) {
        let oil = summary(&ld, "Eng Oil Pres", r.start, r.end);
        let rpm = summary(&ld, "Engine RPM", r.start, r.end);
        let coolant = summary(&ld, "Engine Temp", r.start, r.end);
        let actual = [
            oil.min.unwrap(),
            rpm.min.unwrap(),
            rpm.max.unwrap(),
            rpm.average.unwrap(),
            coolant.max.unwrap(),
        ];
        println!("{}: {actual:?}", r.name);
        for (i, (v, e)) in actual.into_iter().zip(expected).enumerate() {
            let tolerance = if i == 0 || i == 4 { 0.11 } else { 1. };
            assert!((v - e).abs() < tolerance, "{v} != {e}");
        }
    }
}
